def experiment(inputs):
    history = inputs.get('history', [])
    results = []
    for t in history:
        if isinstance(t, dict) and 'transition_id' in t:
            results.append(1.0)
        elif t is None:
            results.append(1.0)
        else:
            results.append(0.0)
    return {'verification_accuracy': sum(results) / len(results) if results else 0.0}
